import { NavLink } from 'react-router-dom';
import styled from 'styled-components';

const views = [
  { title: 'Staff', path: '/sandbox/staff' },
  { title: 'Flying Notes', path: '/sandbox/flying-notes' },
  { title: 'Guitar', path: '/sandbox/tablature-guitar' },
  { title: 'Drop D guitar', path: '/sandbox/tablature-guitar-drop-d' },
  { title: 'Bass guitar', path: '/sandbox/tablature-bass' },
  { title: 'Ukulele', path: '/sandbox/tablature-ukulele' },
];

export const SandboxViews = () => (
  <ViewNavigation aria-label="Note display">
    <ViewLabel>Display</ViewLabel>
    <ViewList>
      {views.map(({ title, path }) => (
        <li key={path}>
          <ViewLink to={path} title={title} end>
            <ViewIcon path={path} />
            {title}
          </ViewLink>
        </li>
      ))}
    </ViewList>
  </ViewNavigation>
);

const ViewIcon = ({ path }: { path: string }) => {
  const staff = path === '/sandbox/staff';
  const flying = path === '/sandbox/flying-notes';
  const dropD = path.endsWith('guitar-drop-d');
  const bass = path.endsWith('bass');
  const ukulele = path.endsWith('ukulele');
  return (
    <svg
      width="20"
      height="20"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.5"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      focusable="false"
    >
      {staff ? (
        <>
          <path d="M3 6h18M3 10h18M3 14h18M3 18h18M15 5v11" />
          <ellipse cx="12.5" cy="16.5" rx="2.5" ry="1.8" fill="currentColor" />
        </>
      ) : flying ? (
        <>
          <rect x="3" y="14" width="18" height="7" rx="1.5" />
          <path d="M7 14v7m5-7v7m5-7v7M12 10V3m-3 3 3-3 3 3" />
        </>
      ) : (
        <>
          <path
            d={
              ukulele
                ? 'M11 10V3h3v7c4 0 5 3 3 5 4 5-1 8-5 7-5 0-6-4-3-7-2-2-1-5 2-5Z'
                : 'M10 10V2h4v8c4-1 6 2 3 5 5 4 1 8-5 7-6 1-10-3-5-7-3-3-1-6 3-5Z'
            }
          />
          <circle cx="12" cy="15" r={bass ? '1.5' : '2'} />
          <path d="M9 19h6M10 5h4M10 7h4" />
          {bass && <path d="M9 2h1m4 2h1" />}
          {dropD && (
            <text
              x="17"
              y="9"
              fill="currentColor"
              stroke="none"
              fontSize="8"
              fontFamily="sans-serif"
              fontWeight="700"
            >
              D
            </text>
          )}
        </>
      )}
    </svg>
  );
};

const ViewNavigation = styled.nav`
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  overflow-x: auto;
  padding: 4px;
`;

const ViewLabel = styled.span`
  color: ${p => p.theme.textSecondary};
  flex-shrink: 0;
  font-size: 10px;
`;

const ViewList = styled.ul`
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: 2px;
  margin: 0;
  padding: 0;
  list-style: none;

  li {
    display: flex;
  }
`;

const ViewLink = styled(NavLink)`
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 32px;
  padding: 0 8px;
  border-radius: 6px;
  color: ${p => p.theme.textSecondary};
  font-size: 12px;
  text-decoration: none;
  white-space: nowrap;

  svg {
    flex-shrink: 0;
    width: 16px;
    height: 16px;
  }

  &:visited {
    color: ${p => p.theme.textSecondary};
  }

  &:hover,
  &[aria-current='page'] {
    color: ${p => p.theme.primary};
    background: ${p => p.theme.borderLight};
  }

  &[aria-current='page'] {
    box-shadow: inset 0 -2px ${p => p.theme.primary};
  }

  @media (pointer: coarse) {
    min-height: 44px;
  }
`;
