import { useCallback, useEffect, useMemo, useState } from 'react';
import { Helmet } from 'react-helmet-async';
import styled from 'styled-components';

import {
  MAX_TEMPO,
  MIN_TEMPO,
  clampTempo,
} from 'app/services/MelodiesService/tempo';
import { useLibraryPlayback } from 'app/services/MelodiesService/useLibraryPlayback';
import type { Note } from 'app/services/NotesService/types';
import { MAX_FRET } from 'app/services/TablatureService/fingering';
import {
  GuitarTuning,
  TabCursor,
  TabEditor,
  TabNote,
  emptyStep,
  insertGuitarNote,
  loadTabDraft,
  saveTabDraft,
  writeTabNote,
} from 'app/services/TablatureService/tabCreator';
import {
  tabMelody,
  tabStepDuration,
} from 'app/services/TablatureService/tabPlayback';
import { STRINGS } from 'app/services/TablatureService/tuning';

import { GuitarEntry } from 'app/components/TabCreator/GuitarEntry';
import { TabDownloads } from 'app/components/TabCreator/TabDownloads';
import { TabGrid } from 'app/components/TabCreator/TabGrid';
import { PageTitle } from 'app/components/_styled/PageTitle';
import { PageWrapper } from 'app/components/_styled/PageWrapper';

const frets = Array.from({ length: MAX_FRET + 1 }, (_, fret) => fret);

export const TabCreatorPage = () => {
  const [{ draft, cursor }, setEditor] = useState<TabEditor>(() => ({
    draft: loadTabDraft(),
    cursor: { step: 0, string: 0 },
  }));
  const [guitarMode, setGuitarMode] = useState(false);
  const [entering, setEntering] = useState(false);
  const note = draft.steps[cursor.step][cursor.string];
  const melody = useMemo(() => tabMelody(draft), [draft]);
  const playback = useLibraryPlayback();
  const playing = !!playback.activeTitle;
  const editingLocked = entering || playing;
  const playingStep =
    playing && !playback.loading
      ? Math.floor(playback.position / tabStepDuration(draft.bpm))
      : undefined;

  useEffect(() => saveTabDraft(draft), [draft]);

  const enterGuitarNote = useCallback(
    (pitch: Note) => setEditor(current => insertGuitarNote(current, pitch)),
    [],
  );

  const changeFret = (at: TabCursor, fret: number | null) =>
    setEditor(current => {
      const oldNote = current.draft.steps[at.step][at.string];
      const nextNote =
        fret === null
          ? null
          : {
              ...oldNote,
              fret,
              slide: oldNote?.slide === fret ? undefined : oldNote?.slide,
            };
      return { ...current, draft: writeTabNote(current.draft, at, nextNote) };
    });

  const changeNote = (nextNote: TabNote) =>
    setEditor(current => ({
      ...current,
      draft: writeTabNote(current.draft, cursor, nextNote),
    }));

  const addStep = () =>
    setEditor(current => ({
      draft: {
        ...current.draft,
        steps: [...current.draft.steps, emptyStep()],
      },
      cursor: { ...current.cursor, step: current.draft.steps.length },
    }));

  const removeStep = () =>
    setEditor(current => {
      const steps = current.draft.steps.filter(
        (_, index) => index !== current.cursor.step,
      );
      return {
        draft: { ...current.draft, steps },
        cursor: {
          ...current.cursor,
          step: Math.min(current.cursor.step, steps.length - 1),
        },
      };
    });

  const setMode = (guitar: boolean) => {
    if (guitar === guitarMode) return;
    setEntering(false);
    setGuitarMode(guitar);
  };

  return (
    <Page aria-labelledby="tab-creator-title" data-local-space-key>
      <Helmet>
        <title>Tab Creator</title>
      </Helmet>
      <Heading>
        <PageTitle id="tab-creator-title">Tab Creator</PageTitle>
        <p>
          Type fret numbers into the grid or play notes on your guitar to fill
          it.
        </p>
      </Heading>
      <Toolbar>
        <Modes role="group" aria-label="Note entry mode">
          <button
            type="button"
            aria-pressed={!guitarMode}
            onClick={() => setMode(false)}
          >
            Manual
          </button>
          <button
            type="button"
            aria-pressed={guitarMode}
            onClick={() => setMode(true)}
          >
            Guitar input
          </button>
        </Modes>
        <label>
          Tuning
          <select
            value={draft.tuning}
            disabled={editingLocked}
            onChange={event => {
              const tuning = event.target.value as GuitarTuning;
              setEditor(current => ({
                ...current,
                draft: { ...current.draft, tuning },
              }));
            }}
          >
            <option value="guitar">Standard (E A D G B E)</option>
            <option value="guitarDropD">Drop D (D A D G B E)</option>
          </select>
        </label>
      </Toolbar>
      {guitarMode && (
        <GuitarEntry
          entering={entering}
          playing={playing}
          onEntering={setEntering}
          onNote={enterGuitarNote}
        />
      )}
      <Editor aria-label="Tab editor">
        <Toolbar>
          <div>
            <h2>Tablature</h2>
            <p>
              Choose a cell and type a fret from 0 to {MAX_FRET}. Use the arrow
              keys to move.
            </p>
          </div>
          <Actions>
            <button type="button" disabled={editingLocked} onClick={addStep}>
              Add step
            </button>
            <button
              type="button"
              disabled={editingLocked || draft.steps.length === 1}
              onClick={removeStep}
              aria-label={`Remove step ${cursor.step + 1}`}
            >
              Remove step
            </button>
          </Actions>
        </Toolbar>
        <Transport role="group" aria-label="Tab playback and downloads">
          <label>
            Tempo (BPM)
            <input
              type="number"
              min={MIN_TEMPO}
              max={MAX_TEMPO}
              step={1}
              defaultValue={draft.bpm}
              disabled={editingLocked}
              onKeyDown={event => {
                if (event.key === 'Enter') event.currentTarget.blur();
              }}
              onBlur={event => {
                const field = event.currentTarget;
                const bpm = Number.isFinite(field.valueAsNumber)
                  ? clampTempo(field.valueAsNumber)
                  : draft.bpm;
                field.value = String(bpm);
                if (bpm !== draft.bpm)
                  setEditor(current => ({
                    ...current,
                    draft: { ...current.draft, bpm },
                  }));
              }}
            />
          </label>
          <button
            type="button"
            className="selected"
            disabled={entering || !melody.notes.length}
            onClick={() => void playback.toggle(melody)}
          >
            {playback.loading ? 'Cancel playback' : playing ? 'Stop' : 'Play'}
          </button>
          <TabDownloads draft={draft} melody={melody} />
          <p>
            Each column lasts an eighth note. Leave a column empty for a rest.
          </p>
          {playback.error && <p role="alert">{playback.error}</p>}
        </Transport>
        <TabGrid
          draft={draft}
          cursor={cursor}
          playingStep={playingStep}
          readOnly={editingLocked}
          onSelect={at => setEditor(current => ({ ...current, cursor: at }))}
          onFret={changeFret}
        />
        <Details>
          <div>
            <h2>Note techniques</h2>
            <p>
              Step {cursor.step + 1} · String {cursor.string + 1} (
              {STRINGS[draft.tuning][cursor.string]})
            </p>
          </div>
          {note && !editingLocked ? (
            <Actions>
              <label>
                Technique
                <select
                  value={
                    note.slide !== undefined ? 'slide' : note.bend ? 'bend' : ''
                  }
                  onChange={event => {
                    const value = event.target.value;
                    changeNote({
                      ...note,
                      slide:
                        value === 'slide'
                          ? note.fret === MAX_FRET
                            ? note.fret - 1
                            : note.fret + 1
                          : undefined,
                      bend: value === 'bend' ? 2 : undefined,
                    });
                  }}
                >
                  <option value="">None</option>
                  <option value="slide">Slide</option>
                  <option value="bend">Bend</option>
                </select>
              </label>
              {note.slide !== undefined && (
                <label>
                  Slide to fret
                  <select
                    value={note.slide}
                    onChange={event =>
                      changeNote({ ...note, slide: Number(event.target.value) })
                    }
                  >
                    {frets
                      .filter(fret => fret !== note.fret)
                      .map(fret => (
                        <option key={fret} value={fret}>
                          {fret}
                        </option>
                      ))}
                  </select>
                </label>
              )}
              {note.bend !== undefined && (
                <label>
                  Bend amount
                  <select
                    value={note.bend}
                    onChange={event =>
                      changeNote({ ...note, bend: Number(event.target.value) })
                    }
                  >
                    <option value={1}>½ step</option>
                    <option value={2}>Whole step</option>
                    <option value={3}>1½ steps</option>
                  </select>
                </label>
              )}
              <Check>
                <input
                  type="checkbox"
                  checked={!!note.vibrato}
                  onChange={event =>
                    changeNote({ ...note, vibrato: event.target.checked })
                  }
                />
                Vibrato
              </Check>
              <button type="button" onClick={() => changeFret(cursor, null)}>
                Clear note
              </button>
            </Actions>
          ) : (
            <p>
              {entering
                ? 'Stop note entry to edit techniques.'
                : playing
                ? 'Stop playback to edit techniques.'
                : 'Enter a fret to add techniques to this note.'}
            </p>
          )}
        </Details>
      </Editor>
    </Page>
  );
};

const Page = styled(PageWrapper)`
  max-width: 1080px;
  display: grid;
  gap: 16px;

  p {
    margin: 0;
    color: ${p => p.theme.textSecondary};
  }

  h2 {
    font-size: 16px;
    font-weight: 650;
  }
`;

const Heading = styled.header`
  p {
    margin-top: 6px;
  }
`;

const Actions = styled.div`
  display: flex;
  align-items: end;
  flex-wrap: wrap;
  gap: 8px;
  min-width: 0;

  label {
    display: grid;
    gap: 4px;
    font-size: 13px;
    color: ${p => p.theme.textSecondary};
  }
`;

const Toolbar = styled(Actions)`
  justify-content: space-between;
  align-items: center;
`;

const Modes = styled.div`
  display: flex;
  gap: 4px;
  padding: 4px;
  border: 1px solid ${p => p.theme.border};
  border-radius: 10px;
  background: ${p => p.theme.backgroundVariant};

  button {
    border-color: transparent;
    background: transparent;
  }

  button[aria-pressed='true'] {
    background: ${p => p.theme.surface};
    border-color: ${p => p.theme.border};
    color: ${p => p.theme.primary};
  }
`;

const Editor = styled.section`
  display: grid;
  gap: 16px;
  min-width: 0;
  padding: 16px;
  border: 1px solid ${p => p.theme.border};
  border-radius: 14px;
  background: ${p => p.theme.surface};

  p {
    font-size: 14px;
  }

  @media (max-width: 520px) {
    padding: 12px;
  }
`;

const Transport = styled(Actions)`
  padding-bottom: 12px;
  border-bottom: 1px solid ${p => p.theme.border};

  input {
    width: 88px;
  }

  p {
    flex-basis: 100%;
  }

  p[role='alert'] {
    color: ${p => p.theme.danger};
  }
`;

const Details = styled.div`
  display: grid;
  gap: 8px;
  padding-top: 12px;
  border-top: 1px solid ${p => p.theme.border};
`;

const Check = styled.label`
  && {
    display: flex;
    align-items: center;
    gap: 6px;
    min-height: 40px;
    padding: 0 8px;
  }
`;
