import { readPreferences, writePreferences } from 'utils/preferences';

export const NOISE_GATE_KEY = 'qwertophone.input-noise-gate.v1';
export interface NoiseGateSettings {
  enabled: boolean;
  threshold: number;
  release: number;
}

export const defaultNoiseGate: NoiseGateSettings = {
  enabled: false,
  threshold: -50,
  release: 150,
};

export const normalizeNoiseGate = (
  value: Partial<NoiseGateSettings>,
): NoiseGateSettings => {
  const number = (next: unknown, fallback: number, min: number, max: number) =>
    typeof next === 'number' && Number.isFinite(next)
      ? Math.min(max, Math.max(min, next))
      : fallback;
  return {
    enabled: value.enabled === true,
    threshold: number(value.threshold, -50, -80, -10),
    release: number(value.release, 150, 20, 1000),
  };
};

export const loadNoiseGate = () =>
  normalizeNoiseGate(readPreferences(NOISE_GATE_KEY));
export const saveNoiseGate = (value: NoiseGateSettings) =>
  writePreferences(NOISE_GATE_KEY, normalizeNoiseGate(value));
