export const FretInlays = memo(function FretInlays({
  markers,
}: {
  markers: FretMarkerStyle;
}) {
  return (
    <Inlays aria-hidden="true">
      {markers === 'vine' && (
        <svg viewBox="0 0 800 100" preserveAspectRatio="none" data-vine>
          <VineArtwork />
        </svg>
      )}
      {guitarFrets.map(fret => {
        const marked = markedFrets.includes(fret);
        const octave = fret === 12 || fret === 24;
        const firstFret =
          fret === 1 && (markers === 'trapezoids' || markers === 'sharktooth');
        return (
          <span key={fret}>
            {markers === 'dots' && marked && (
              <>
                <i />
                {octave && <i />}
              </>
            )}
            {markers !== 'dots' &&
              markers !== 'none' &&
              markers !== 'vine' &&
              (marked || firstFret) && (
                <svg
                  viewBox="0 0 32 64"
                  preserveAspectRatio="none"
                  data-marker={markers}
                >
                  {shapeArtwork[markers]}
                </svg>
              )}
          </span>
        );
      })}
    </Inlays>
  );
});

