import { DrumMachineState, DrumTrack } from './patterns';
import { PreparedDrumSample } from './samples';

export interface DrumPlayback extends DrumMachineState {
  bpm: number;
  steps: number;
}

export interface DrumOutput {
  loadSample: (sample: PreparedDrumSample, blob?: Blob) => Promise<void>;
  now: () => number;
  hit: (
    track: DrumTrack,
    when: number,
    options?: { preview?: boolean },
  ) => void;
  update: (state: DrumMachineState) => void;
  stop: () => void;
  dispose: () => void;
}

// Timers fill a short queue; AudioContext.currentTime determines each onset.
export const createDrumTransport = (
  output: DrumOutput,
  read: () => DrumPlayback,
  onStep: (step: number) => void,
) => {
  let timer: ReturnType<typeof setInterval> | undefined;
  let nextTime = 0;
  let nextStep = 0;
  let visibleSteps: { step: number; when: number }[] = [];

  const tick = () => {
    const state = read();
    const duration = 60 / state.bpm / 4;
    const now = output.now();
    output.update(state);
    // Recover from background throttling without playing a burst of old hits.
    if (nextTime < now - 0.1) {
      const skipped = Math.ceil((now - nextTime) / duration);
      nextStep = (nextStep + skipped) % state.steps;
      nextTime += skipped * duration;
      visibleSteps = [];
    }
    // Hidden tabs may only wake timers once a second. Queue enough audio to
    // bridge those callbacks; keep edits responsive while the tab is visible.
    const lookahead = document.hidden ? 1.2 : 0.1;
    while (nextTime < now + lookahead) {
      nextStep %= state.steps;
      for (const id of state.tracks) {
        if (state.pattern[id][nextStep] && !state.muted[id]) {
          output.hit(id, nextTime);
        }
      }
      visibleSteps.push({ step: nextStep, when: nextTime });
      nextTime += duration;
      nextStep = (nextStep + 1) % state.steps;
    }
    let visible: number | undefined;
    while (visibleSteps.length && visibleSteps[0].when <= now) {
      visible = visibleSteps.shift()!.step;
    }
    if (visible !== undefined) onStep(visible);
  };

  const stop = () => {
    if (timer !== undefined) clearInterval(timer);
    timer = undefined;
    document.removeEventListener('visibilitychange', tick);
    visibleSteps = [];
    output.stop();
    onStep(-1);
  };

  return {
    start() {
      stop();
      nextStep = 0;
      nextTime = output.now() + 0.03;
      tick();
      timer = setInterval(tick, 25);
      document.addEventListener('visibilitychange', tick);
    },
    stop,
  };
};
