import { getNoteDuration } from 'app/services/MelodiesService/timing';
import { Melody } from 'app/services/MelodiesService/types';

const MAX_SILENCE = 3000;

// Keep note indices and recorded times intact. Only the transport skips time,
// and guide audio uses the same mapping. Notes sound in [start, end).
export const createPlaybackTimeline = (
  notes: Melody['notes'],
  hitWindow: number,
) => {
  const silences: { start: number; end: number; previousStart: number }[] = [];
  let end = 0;
  let previousStart = -Infinity;
  [...notes]
    .sort((a, b) => a.start - b.start)
    .forEach(note => {
      if (note.start > end)
        silences.push({ start: end, end: note.start, previousStart });
      end = Math.max(end, note.start + getNoteDuration(note));
      previousStart = note.start;
    });

  const skipped = (silence: typeof silences[number], speed: number) =>
    Math.max(0, silence.end - silence.start - MAX_SILENCE * speed);
  // Short notes must retain their full inclusive late-hit window. Move the
  // skipped section within the silence rather than extending its three seconds.
  const skipStart = (silence: typeof silences[number], speed: number) =>
    Math.max(silence.start, silence.previousStart + hitWindow * speed);

  return {
    toPlaybackTime: (time: number, speed: number) =>
      time -
      silences.reduce(
        (total, silence) =>
          total +
          Math.max(
            0,
            Math.min(time - skipStart(silence, speed), skipped(silence, speed)),
          ),
        0,
      ),
    toSongTime: (time: number, speed: number) =>
      silences.reduce(
        (song, silence) =>
          song >= silence.start &&
          song > silence.previousStart + hitWindow * speed
            ? song + skipped(silence, speed)
            : song,
        time,
      ),
  };
};
