import { useEffect } from 'react';
import { useDispatch } from 'react-redux';

import { melodiesActions, useMelodiesSlice } from './slice';

export const useRememberMelodyOpened = (title: string | undefined) => {
  useMelodiesSlice();
  const dispatch = useDispatch();
  useEffect(() => {
    if (title) dispatch(melodiesActions.rememberMelodyOpened(title));
  }, [dispatch, title]);
};
