import {
  makeExpression,
  pitchAt,
} from 'app/services/MelodiesService/expression';
import type { Melody, NoteTechnique } from 'app/services/MelodiesService/types';
import { chromaticNotes } from 'app/services/NotesService/chromaticNotes';
import { getNote, splitNote } from 'app/services/NotesService/noteUtils';
import type { Octave } from 'app/services/NotesService/types';

import { TabDraft, TabNote, techniqueMark } from './tabCreator';
import { STRINGS } from './tuning';

export const tabStepDuration = (bpm: number) => 30000 / bpm;

const tabExpression = ({ fret, slide, bend, vibrato }: TabNote, ms: number) => {
  const techniques: NoteTechnique[] = [];
  if (slide !== undefined) techniques.push('slide');
  if (bend) techniques.push('bend');
  if (vibrato) techniques.push('vibrato');
  if (!techniques.length) return undefined;

  const target = (slide === undefined ? bend ?? 0 : slide - fret) * 100;
  const sweep = [
    { position: 0, cents: 0 },
    { position: 0.12, cents: 0 },
    { position: slide === undefined ? 0.5 : 0.78, cents: target },
    { position: 1, cents: target },
  ];
  if (!vibrato) return makeExpression(sweep, techniques);

  const cycles = Math.max(2, (ms / 1000) * 6);
  const points = Array.from({ length: 49 }, (_, index) => {
    const position = index / 48;
    const depth = Math.max(
      0,
      Math.min(1, (position - 0.16) * 8, (1 - position) * 8),
    );
    return {
      position,
      cents:
        pitchAt(sweep, position) +
        30 * depth * Math.sin(2 * Math.PI * cycles * position),
    };
  });
  return makeExpression(points, techniques);
};

export const tabMelody = ({ tuning, bpm, steps }: TabDraft): Melody => {
  const duration = tabStepDuration(bpm);
  return {
    title: 'Tab Creator',
    timbre: 'guitar',
    scale: 'diatonic',
    mode: 'ionian',
    pitch: 0,
    octave: 3,
    bpm,
    notes: steps.flatMap((step, index) =>
      step.flatMap((cell, string) => {
        if (!cell) return [];
        const [name, octave] = splitNote(STRINGS[tuning][string]);
        const pitch = octave * 12 + chromaticNotes.indexOf(name) + cell.fret;
        const expression = tabExpression(cell, duration);
        return [
          {
            note: getNote(
              chromaticNotes[pitch % 12],
              Math.floor(pitch / 12) as Octave,
            ),
            start: index * duration,
            duration,
            ...(expression ? { expression } : {}),
            tablature: { [tuning]: { string, fret: cell.fret } },
          },
        ];
      }),
    ),
  };
};

const STEPS_PER_LINE = 8;
export const tabText = ({ tuning, bpm, steps }: TabDraft) => {
  let end = steps.length;
  while (end > 0 && !steps[end - 1].some(Boolean)) end--;
  const lines = [
    'Tab Creator',
    `${
      tuning === 'guitar' ? 'Standard' : 'Drop D'
    } tuning · ${bpm} BPM · eighth-note steps`,
    'Symbols  / slide up   \\ slide down   b bend to pitch   ~ vibrato',
  ];

  for (let start = 0; start < end; start += STEPS_PER_LINE) {
    const columns = steps
      .slice(start, Math.min(start + STEPS_PER_LINE, end))
      .map(step => {
        const cells = step.map(note =>
          note ? `${note.fret}${techniqueMark(note)}` : '',
        );
        return {
          cells,
          width: Math.max(3, ...cells.map(cell => cell.length + 2)),
        };
      });
    lines.push(
      '',
      ...STRINGS[tuning].map(
        (name, string) =>
          `${name}|${columns
            .map(({ cells, width }) => `-${cells[string]}`.padEnd(width, '-'))
            .join('')}|`,
      ),
    );
  }
  return `${lines.join('\n')}\n`;
};
