export const EffectPedalCard = ({
  id,
  name,
  description,
  active,
  pressed,
  disabled,
  compact,
  onToggle,
  action,
}: {
  id: string;
  name: string;
  description?: string;
  active: boolean;
  pressed?: boolean;
  disabled?: boolean;
  compact?: boolean;
  onToggle: () => void;
  action: string;
}) => {
  const design = getPedalDesign(id);
  const [paint, ink, accent] = pedalFinishes[design.finish];
  return (
    <Pedal
      type="button"
      $paint={paint}
      $ink={ink}
      $accent={accent}
      $compact={compact}
      data-graphic={design.graphic}
      data-active={active}
      aria-label={action}
      aria-pressed={pressed}
      disabled={disabled}
      onClick={onToggle}
      title={description}
    >
      <Rivet aria-hidden="true" />
      <Rivet aria-hidden="true" />
      <Brand aria-hidden="true">
        QW / {design.variant.toString().padStart(2, '0')}
      </Brand>
      <Name>{name}</Name>
      <Art>
        <Graphic design={design} />
      </Art>
      <Footswitch aria-hidden="true">
        <Led aria-hidden="true" data-on={active} />
        <Switch aria-hidden="true" />
        <span>{active ? 'ON' : 'OFF'}</span>
      </Footswitch>
    </Pedal>
  );
};

