import { useLayoutEffect, useRef } from 'react';
import { useSelector } from 'react-redux';
import styled from 'styled-components';

import {
  EffectPreset,
  builtInEffectPresets,
  canAddPresetPedal,
  effectPresetCategories,
  togglePresetPedal,
} from 'app/services/EffectsService/presets';
import { selectEffects } from 'app/services/EffectsService/selectors';
import { InstrumentEffects } from 'app/services/EffectsService/settings';
import { guitarOverdrive } from 'app/services/VirtualGuitarService/sound';

import { EffectPedalCard } from 'app/components/EffectPedalCard';

export const GuitarPedals = ({
  settings,
  onChange,
}: {
  settings: InstrumentEffects;
  onChange: (settings: InstrumentEffects) => void;
}) => {
  const { customPresets = [] } = useSelector(selectEffects);
  const pedals = settings.pedals ?? [];
  const available = (preset: EffectPreset) =>
    !pedals.some(pedal => pedal.presetId === preset.id) &&
    canAddPresetPedal(settings, preset);
  const presets = [
    guitarOverdrive,
    ...builtInEffectPresets,
    ...customPresets,
  ].filter(preset => preset.id !== 'clean' && available(preset));
  const chain = useRef<HTMLUListElement>(null);
  const added = useRef(false);
  const addPedal = useRef<HTMLSelectElement>(null);

  useLayoutEffect(() => {
    if (added.current && chain.current) {
      chain.current.scrollLeft = chain.current.scrollWidth;
      added.current = false;
    }
  }, [pedals.length]);

  return (
    <Pedalboard role="group" aria-label="Effects pedals">
      {pedals.length > 0 && (
        <Chain ref={chain} aria-label="Pedal order">
          {pedals.map(pedal => (
            <Slot key={pedal.id}>
              <EffectPedalCard
                compact
                id={pedal.presetId}
                name={pedal.name}
                description={pedal.name}
                active={pedal.enabled}
                pressed={pedal.enabled}
                action={pedal.name}
                onToggle={() =>
                  onChange({
                    ...settings,
                    pedals: pedals.map(item =>
                      item.id === pedal.id
                        ? { ...item, enabled: !item.enabled }
                        : item,
                    ),
                  })
                }
              />
              <Remove
                type="button"
                aria-label={`Remove ${pedal.name}`}
                title={`Remove ${pedal.name}`}
                onClick={() => {
                  onChange({
                    ...settings,
                    pedals: pedals.filter(item => item.id !== pedal.id),
                  });
                  addPedal.current?.focus();
                }}
              >
                <span aria-hidden="true">×</span>
              </Remove>
            </Slot>
          ))}
        </Chain>
      )}
      <Add>
        <span aria-hidden="true">+</span>
        {presets.length ? 'Add pedal' : 'Board full'}
        <select
          ref={addPedal}
          aria-label="Add pedal"
          disabled={!presets.length}
          value=""
          onChange={event => {
            const preset = presets.find(item => item.id === event.target.value);
            if (!preset) return;
            added.current = true;
            onChange(togglePresetPedal(settings, preset));
          }}
        >
          <option value="" disabled>
            Add pedal
          </option>
          {available(guitarOverdrive) && (
            <option value={guitarOverdrive.id}>{guitarOverdrive.name}</option>
          )}
          {effectPresetCategories.map(category => {
            const options = builtInEffectPresets.filter(
              preset =>
                preset.category === category.id &&
                presets.some(item => item.id === preset.id),
            );
            if (!options.length) return null;
            return (
              <optgroup key={category.id} label={category.name}>
                {options.map(preset => (
                  <option key={preset.id} value={preset.id}>
                    {preset.name}
                  </option>
                ))}
              </optgroup>
            );
          })}
          {customPresets.some(available) && (
            <optgroup label="My Presets">
              {customPresets.filter(available).map(preset => (
                <option key={preset.id} value={preset.id}>
                  {preset.name}
                </option>
              ))}
            </optgroup>
          )}
        </select>
      </Add>
    </Pedalboard>
  );
};

const Pedalboard = styled.div`
  display: flex;
  align-items: center;
  gap: clamp(6px, 1vw, 16px);
  min-width: 0;
  height: var(--gear-size);
  --pedal-width: clamp(66px, calc(var(--gear-size) * 0.67), 120px);
`;

const Chain = styled.ul`
  display: flex;
  align-self: stretch;
  gap: clamp(10px, 1vw, 16px);
  min-width: 0;
  margin: 0;
  padding: 0 6px 4px;
  overflow: auto hidden;
  overscroll-behavior-x: contain;
  list-style: none;
`;

const Slot = styled.li`
  position: relative;
  flex: 0 0 var(--pedal-width);
  padding-top: 14px;
`;

const Remove = styled.button`
  position: absolute;
  z-index: 1;
  top: 0;
  right: -4px;
  display: grid;
  place-items: start end;
  width: 40px;
  height: 40px;
  padding: 0;
  border: 0;
  background: transparent;

  span {
    display: grid;
    place-items: center;
    width: 23px;
    height: 23px;
    border: 1px solid ${p => p.theme.border};
    border-radius: 50%;
    background: ${p => p.theme.surface};
    font-size: 17px;
    line-height: 1;
  }

  &:hover span {
    border-color: ${p => p.theme.primary};
  }
`;

const Add = styled.label`
  position: relative;
  display: grid;
  align-content: center;
  justify-items: center;
  flex: 0 0 var(--pedal-width);
  height: calc(var(--gear-size) - 22px);
  border: 1px dashed ${p => p.theme.border};
  border-radius: 12px;
  color: ${p => p.theme.textSecondary};
  font-size: clamp(11px, 1.4vw, 14px);
  font-weight: 600;

  span {
    color: ${p => p.theme.primary};
    font-size: 26px;
    line-height: 1.15;
  }

  &:hover,
  &:focus-within {
    border-color: ${p => p.theme.primary};
    color: ${p => p.theme.text};
  }

  select {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    opacity: 0;
    cursor: pointer;
  }
`;
