import { useEffect, useState } from 'react';
import { Helmet } from 'react-helmet-async';
import styled from 'styled-components';

import { normalizeEffects } from 'app/services/EffectsService/settings';
import {
  defaultGuitarEffects,
  guitarTimbres,
} from 'app/services/VirtualGuitarService/sound';

import { instrumentImage } from 'app/components/TimbrePicker/catalog';
import {
  FretMarkerPreview,
  FretMarkerStyle,
  fretMarkerOptions,
} from 'app/components/VirtualGuitar/FretMarkers';
import { Fretboard } from 'app/components/VirtualGuitar/Fretboard';
import { GuitarPedals } from 'app/components/VirtualGuitar/GuitarPedals';
import {
  BoardLabels,
  BoardPanel,
  Cell,
  Feedback,
} from 'app/components/VirtualGuitar/styles';
import { PageWrapper } from 'app/components/_styled/PageWrapper';

import { readPreferences, writePreferences } from 'utils/preferences';

const preferencesKey = 'qwertophone.virtual-guitar.v1';

export const VirtualGuitarPage = () => {
  const [preferences] = useState(() => readPreferences(preferencesKey));
  const [guitar, setGuitar] = useState(
    () =>
      guitarTimbres.find(option => option.id === preferences.timbre) ??
      guitarTimbres[0],
  );
  const [effects, setEffects] = useState(() =>
    preferences.effects
      ? normalizeEffects('', preferences.effects)
      : defaultGuitarEffects(),
  );
  const [markers, setMarkers] = useState<FretMarkerStyle>(
    () =>
      fretMarkerOptions.find(option => option.value === preferences.markers)
        ?.value ?? 'dots',
  );

  useEffect(() => {
    writePreferences(preferencesKey, { markers, timbre: guitar.id, effects });
  }, [markers, guitar, effects]);

  return (
    <Page aria-label="Virtual Guitar" data-local-space-key>
      <Helmet>
        <title>Virtual Guitar</title>
      </Helmet>
      <Gear>
        <GuitarBox>
          <span>Guitar</span>
          <img src={instrumentImage(guitar.artwork)} alt="" />
          <select
            value={guitar.id}
            onChange={event => {
              const selected = guitarTimbres.find(
                option => option.id === event.target.value,
              );
              if (selected) setGuitar(selected);
            }}
          >
            {guitarTimbres.map(option => (
              <option key={option.id} value={option.id}>
                {option.label}
              </option>
            ))}
          </select>
        </GuitarBox>
        <GuitarPedals settings={effects} onChange={setEffects} />
      </Gear>
      <PageFretboard
        markers={markers}
        showTab={false}
        sound={{ timbre: guitar.id, effects }}
      />
      <MarkerOptions role="group" aria-label="Fret markers">
        {fretMarkerOptions.map(({ value, label }) => (
          <MarkerButton
            key={value}
            type="button"
            aria-label={label}
            aria-pressed={markers === value}
            onClick={() => setMarkers(value)}
          >
            <FretMarkerPreview markers={value} />
          </MarkerButton>
        ))}
      </MarkerOptions>
    </Page>
  );
};

const Page = styled(PageWrapper)`
  --gear-size: clamp(110px, 25vh, 196px);
  display: flex;
  flex-direction: column;
  gap: clamp(6px, 1.4vh, 16px);
  max-width: none;
  min-height: var(--app-content-height);
  padding: 12px clamp(10px, 2.25vw, 32px) 16px;

  @media (max-width: 600px) {
    --gear-size: clamp(100px, 30vw, 156px);
  }

  @media (max-width: 600px) and (max-height: 620px) {
    --gear-size: 100px;
    gap: 6px;
    padding-top: 8px;
    padding-bottom: 10px;
  }

  @media (max-height: 470px) {
    --gear-size: clamp(72px, calc(var(--app-content-height) * 0.29), 100px);
    gap: 4px;
    padding-top: 4px;
    padding-bottom: 6px;
  }
`;

const Gear = styled.div`
  display: grid;
  flex: 1;
  grid-template-columns: var(--gear-size) minmax(0, 1fr);
  align-items: center;
  gap: clamp(8px, 1.5vw, 24px);
`;

const GuitarBox = styled.label`
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  height: var(--gear-size);
  padding: clamp(5px, 1vw, 12px);
  border: 1px solid ${p => p.theme.border};
  border-radius: 12px;
  background: ${p => p.theme.surface};
  color: ${p => p.theme.textSecondary};
  font-size: clamp(11px, 1.25vw, 14px);
  font-weight: 600;
  text-align: center;

  img {
    width: 100%;
    height: 100%;
    object-fit: contain;
  }

  select {
    width: 100%;
    min-width: 0;
    min-height: clamp(32px, 4.5vh, 44px);
    padding: 3px 2px;
    border-color: ${p => p.theme.border};
    background: ${p => p.theme.background};
    font-weight: 600;
    cursor: pointer;
  }

  @media (max-height: 470px) {
    padding: 4px;
  }
`;

const PageFretboard = styled(Fretboard)`
  & ${BoardPanel} {
    position: relative;
    min-width: 0;
    padding: 0;
    border: 0;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
  }

  & ${Cell} {
    min-height: clamp(
      26px,
      min(
        6.8vh,
        calc((var(--app-content-height) - var(--gear-size) - 140px) / 6)
      ),
      70px
    );
  }

  & ${Feedback} {
    position: absolute;
    right: 0;
    bottom: 100%;
    z-index: 3;
    margin: 0;
    padding: 4px 8px;
    border-radius: 8px;
    background: ${p => p.theme.surface};
  }

  @media (max-height: 470px) {
    padding-right: 54px;

    & ${Cell} {
      display: grid;
      place-items: center;
      min-height: clamp(
        16px,
        calc((var(--app-content-height) - var(--gear-size) - 86px) / 6),
        28px
      );

      span {
        font-size: 10px;
        line-height: 1.2;
      }
    }

    & ${BoardLabels} {
      min-height: 20px;
    }
  }
`;

const MarkerOptions = styled.div`
  display: grid;
  grid-template-columns: repeat(${fretMarkerOptions.length}, minmax(0, 60px));
  justify-content: center;
  gap: 6px;

  @media (max-width: 460px) {
    padding-right: 54px;
  }
`;

const MarkerButton = styled.button`
  display: grid;
  place-items: center;
  min-height: 44px;
  min-width: 0;
  padding: 3px;
  border: 1px solid ${p => p.theme.border};
  border-radius: 7px;
  background: ${p => p.theme.surface};
  cursor: pointer;

  &[aria-pressed='true'] {
    border-color: ${p => p.theme.primary};
    box-shadow: inset 0 0 0 1px ${p => p.theme.primary};
  }

  &:hover {
    background: ${p => p.theme.borderLight};
  }

  &:focus-visible {
    outline: 2px solid ${p => p.theme.primary};
    outline-offset: 1px;
  }

  > svg {
    display: block;
    width: 100%;
  }

  @media (max-height: 470px) {
    min-height: 34px;

    > svg {
      max-height: 26px;
    }
  }
`;
