import {
  TimeSignature,
  getTimeSignature,
} from 'app/services/MelodiesService/meter';

export const METRONOME_METERS = {
  '2/4': { unit: 4, groups: [2] },
  '3/4': { unit: 4, groups: [3] },
  '4/4': { unit: 4, groups: [4] },
  '5/4': { unit: 4, groups: [3, 2] },
  '3/8': { unit: 8, groups: [3] },
  '6/8': { unit: 8, groups: [3, 3] },
  '7/8': { unit: 8, groups: [2, 2, 3] },
  '9/8': { unit: 8, groups: [3, 3, 3] },
  '12/8': { unit: 8, groups: [3, 3, 3, 3] },
} as const;

export type MetronomeTimeSignature = keyof typeof METRONOME_METERS;
export type MetronomeMeter = 'recording' | MetronomeTimeSignature;

export const METRONOME_RHYTHMS = {
  beats: { label: 'Steady beats', offsets: [0] },
  duplets: { label: 'Two notes per beat', offsets: [0, 1 / 2] },
  sixteenths: {
    label: 'Four notes per beat',
    offsets: [0, 1 / 4, 1 / 2, 3 / 4],
  },
  triplets: { label: 'Triplets', offsets: [0, 1 / 3, 2 / 3] },
  swing: { label: 'Swing (2:1)', offsets: [0, 2 / 3] },
  dotted: { label: 'Dotted (3:1)', offsets: [0, 3 / 4] },
} as const;

export type MetronomeRhythm = keyof typeof METRONOME_RHYTHMS;

export const getMetronomeMeter = (value: unknown): MetronomeMeter =>
  typeof value === 'string' &&
  Object.prototype.hasOwnProperty.call(METRONOME_METERS, value)
    ? (value as MetronomeTimeSignature)
    : 'recording';

export const getMetronomeRhythm = (value: unknown): MetronomeRhythm =>
  typeof value === 'string' &&
  Object.prototype.hasOwnProperty.call(METRONOME_RHYTHMS, value)
    ? (value as MetronomeRhythm)
    : 'beats';

export const resolveMetronomeMeter = (
  value: unknown,
  recordingMeter?: TimeSignature,
): MetronomeTimeSignature => {
  const meter = getMetronomeMeter(value);
  return meter === 'recording' ? getTimeSignature(recordingMeter) : meter;
};

export const getMeterBeats = (meter: MetronomeTimeSignature) => {
  const { groups } = METRONOME_METERS[meter];
  let groupStart = 0;
  return groups.flatMap(group => {
    const beats = Array.from({ length: group }, (_, index) => ({
      number: groupStart + index + 1,
      accent: index === 0,
    }));
    groupStart += group;
    return beats;
  });
};

export const createMetronomePattern = (
  meter: MetronomeTimeSignature,
  rhythm: MetronomeRhythm,
  bpm: number,
) => {
  const beatDuration = (60000 / bpm) * (4 / METRONOME_METERS[meter].unit);
  const beats = getMeterBeats(meter);
  const events = beats.flatMap((beat, index) =>
    METRONOME_RHYTHMS[rhythm].offsets.map((offset, subdivision) => ({
      offset: (index + offset) * beatDuration,
      beat: index,
      subdivision,
      accent: beat.accent && subdivision === 0,
    })),
  );
  return { events, beatDuration, duration: beats.length * beatDuration };
};
