import { InstrumentEffects } from 'app/services/EffectsService/settings';
import { Note } from 'app/services/NotesService/types';
import { createEffectsRack } from 'app/services/SynthesizerService/effects';
import {
  noteIndex,
  sampleRegion,
} from 'app/services/SynthesizerService/sampleLayout';
import { sampleDefinition } from 'app/services/SynthesizerService/timbres';
import { SustainLoop, Timbre } from 'app/services/SynthesizerService/types';

import { RealtimeFrame } from './polyphonicStream';

// A separate rack on the capture context preserves the input's output device
// and lets emergency mute cut effect tails without touching keyboard/MIDI voices.
export const createInputTimbrePlayer = (
  audio: AudioContext,
  buffer: AudioBuffer,
  timbre: Timbre,
  settings: InstrumentEffects,
) => {
  const analyser = audio.createAnalyser();
  analyser.fftSize = 1024;
  analyser.connect(audio.destination);
  const rack = createEffectsRack(audio, analyser, settings, {
    cursorKey: timbre,
    continuousCursor: true,
  });
  const definition = sampleDefinition(timbre);
  const sources = new Set<AudioBufferSourceNode>();
  const voices = new Map<
    Note,
    {
      id: number;
      release: () => void;
      source: AudioBufferSourceNode;
      expressive: boolean;
    }
  >();
  let drones: (() => void)[] = [];
  let disposed = false;
  const start = (
    offset: number,
    duration: number,
    playbackRate: number,
    loop?: SustainLoop | null,
    gain = 1,
  ) => {
    const source = audio.createBufferSource();
    const envelope = audio.createGain();
    source.buffer = buffer;
    source.playbackRate.value = playbackRate;
    envelope.gain.value = gain;
    source.connect(envelope);
    envelope.connect(rack.input);
    sources.add(source);
    source.onended = () => {
      sources.delete(source);
      source.disconnect();
      envelope.disconnect();
    };
    const sustained = loop && loop.loopStart < loop.loopEnd;
    if (sustained) {
      source.loop = true;
      source.loopStart = offset + loop.loopStart;
      source.loopEnd = offset + loop.loopEnd;
      source.start(audio.currentTime, offset);
    } else source.start(audio.currentTime, offset, duration);
    const release = () => {
      if (!sources.has(source)) return;
      envelope.gain.setValueAtTime(gain, audio.currentTime);
      envelope.gain.linearRampToValueAtTime(
        0,
        audio.currentTime + definition.release,
      );
      source.stop(audio.currentTime + definition.release);
    };
    return { source, release };
  };
  const levelData = new Float32Array(analyser.fftSize);
  return {
    updateEffects: rack.update,
    update(frame: RealtimeFrame) {
      if (disposed) return;
      const attacks = new Map(
        frame.events.map(event => [event.note.note, event]),
      );
      voices.forEach((voice, note) => {
        if (
          !frame.soundingNotes.includes(note) ||
          (attacks.has(note) && attacks.get(note)!.id !== voice.id)
        ) {
          voice.release();
          voices.delete(note);
        }
      });
      frame.soundingNotes.forEach(note => {
        const existing = voices.get(note);
        if (existing) {
          if (existing.expressive && attacks.has(note))
            existing.source.detune.setTargetAtTime(
              attacks.get(note)!.pitchCents ?? 0,
              audio.currentTime,
              0.01,
            );
          return;
        }
        const region = sampleRegion(
          noteIndex(note),
          definition,
          timbre === 'drums',
          buffer.duration,
        );
        if (!region) return;
        const voice = start(
          region.offset,
          region.duration,
          region.playbackRate,
          region.loop,
        );
        if (region.expressive)
          voice.source.detune.value = attacks.get(note)?.pitchCents ?? 0;
        voices.set(note, {
          id: attacks.get(note)?.id ?? -1,
          ...voice,
          expressive: region.expressive,
        });
      });
      if (voices.size && !drones.length)
        drones = (definition.drones ?? []).map(
          drone =>
            start(drone.offset, drone.duration, 1, drone, drone.gain).release,
        );
      else if (!voices.size) {
        drones.forEach(release => release());
        drones = [];
      }
    },
    level() {
      analyser.getFloatTimeDomainData(levelData);
      let energy = 0,
        peak = 0;
      levelData.forEach(value => {
        energy += value * value;
        peak = Math.max(peak, Math.abs(value));
      });
      return { rms: Math.sqrt(energy / levelData.length), peak };
    },
    dispose() {
      if (disposed) return;
      disposed = true;
      analyser.disconnect();
      rack.dispose();
      sources.forEach(source => source.stop());
      voices.clear();
      drones = [];
    },
  };
};
